FROM public.properties p JOIN (VALUES
('qcent-woods-resort-spa-rishikesh','standard-room','Standard Room','Rooms','A warm, wood-lined room with a private balcony overlooking the resort gardens, fitted with all bath amenities, cable LED TV, intercom and 24-hour room service.','["https://qcenthotels.com/wp-content/uploads/2024/04/1-12.png","https://qcenthotels.com/wp-content/uploads/2024/04/3-12.png"]',280,'1 Queen Bed',2,'["Air Conditioning","Free Wi-Fi","LED TV","Hot & cold running water","Intercom","Power backup"]',4500,'[{"code":"EP","label":"Room Only","price":0},{"code":"CP","label":"With Breakfast","price":700},{"code":"MAP","label":"Breakfast + Dinner","price":1500}]','Free cancellation up to 48 hours before check-in.',6,1),
('qcent-woods-resort-spa-rishikesh','deluxe-room','Deluxe Room','Rooms','A larger room with a seating corner and forest-facing windows, designed for uninterrupted relaxation with all the convenience of home.','["https://qcenthotels.com/wp-content/uploads/2024/04/4-13.png","https://qcenthotels.com/wp-content/uploads/2024/04/5-11.png"]',340,'1 King Bed',3,'["Air Conditioning","Free Wi-Fi","LED TV","Seating area","Laundry service","Doctor on call"]',5400,'[{"code":"EP","label":"Room Only","price":0},{"code":"CP","label":"With Breakfast","price":700},{"code":"MAP","label":"Breakfast + Dinner","price":1500}]','Free cancellation up to 48 hours before check-in.',6,2),
('qcent-woods-resort-spa-rishikesh','deluxe-woods-cottage','Deluxe Woods Cottage','Accommodation Type','A standalone wooden cottage tucked into the trees, with a private sit-out for morning coffee and the sound of the river close by.','["https://qcenthotels.com/wp-content/uploads/2024/03/image_2024_03_21T09_12_09_487Z.png"]',420,'1 King Bed',3,'["Private sit-out","Air Conditioning","Free Wi-Fi","LED TV","Attached washroom","24-hour room service"]',6800,'[{"code":"EP","label":"Room Only","price":0},{"code":"CP","label":"With Breakfast","price":900},{"code":"MAP","label":"Breakfast + Dinner","price":1800}]','Free cancellation up to 48 hours before check-in.',4,3),
('qcent-woods-resort-spa-rishikesh','luxury-woods-cottage','Luxury Woods Cottage','Accommodation Type','The most spacious cottage at the resort, with a wraparound deck for star gazing and a bathtub looking into the woods.','["https://qcenthotels.com/wp-content/uploads/2024/03/image_2024_03_21T09_10_46_561Z.png"]',560,'1 King Bed + Day Bed',4,'["Wraparound deck","Bathtub","Air Conditioning","Free Wi-Fi","LED TV","Mini bar","24-hour room service"]',8900,'[{"code":"EP","label":"Room Only","price":0},{"code":"CP","label":"With Breakfast","price":900},{"code":"MAP","label":"Breakfast + Dinner","price":1800},{"code":"AP","label":"All Meals","price":2600}]','Free cancellation up to 72 hours before check-in.',4,4),
('pacific-inn-360-degree-resort-rishikesh','valley-view-room','Valley View Room','Rooms','Floor-to-ceiling windows framing the Ganga valley, with a compact balcony for sunrise coffee.','["https://qcenthotels.com/wp-content/uploads/2024/04/degree.png"]',300,'1 Queen Bed',2,'["Air Conditioning","Free Wi-Fi","LED TV","Balcony"]',3800,'[{"code":"EP","label":"Room Only","price":0},{"code":"CP","label":"With Breakfast","price":600}]','Free cancellation up to 48 hours before check-in.',8,1),
