('qcent-bairagarh-resort-rishikesh','forest-suite','Forest Suite','Accommodation Type','A quiet suite at the forest edge with a private deck.','["https://qcenthotels.com/wp-content/uploads/2024/04/1-13.png"]',480,'1 King Bed',3,'["Private deck","Air Conditioning","Free Wi-Fi","LED TV"]',5800,'[{"code":"EP","label":"Room Only","price":0},{"code":"MAP","label":"Breakfast + Dinner","price":1400}]','Free cancellation up to 48 hours before check-in.',4,2),
