-- RESTAURANTS
INSERT INTO public.restaurants (property_id,name,description,cuisine,images,timing,seating,features)
SELECT p.id, x.name, x.description, x.cuisine, x.images::jsonb, x.timing, x.seating, x.features::jsonb
FROM public.properties p JOIN (VALUES
('qcent-woods-resort-spa-rishikesh','Multi Cuisine Restaurant','Our restaurant is a place that has got something for everyone, from great food to wonderful music, from the range of cocktails to a gracious and calm ambiance. Our breakfast, lunch and dinner menus offer a wide variety of world cuisine. For those who would prefer a slow-roasted dinner, we have special grilling arrangements which allow everyone to prepare their meal and eat together while enjoying the cracking of the fire. The restaurant has an open place to grab a coffee and some snacks with stunning views of the beautiful surroundings of the hills and the Ganges.','World Cuisine, Indian, Continental','["https://qcenthotels.com/wp-content/uploads/2024/03/multi-uk1-scaled.jpeg"]','07:00 AM - 11:00 PM','80 covers, indoor & open deck','["Live grill","Open-air coffee deck","Ganges & hill views","Live music evenings"]'),
('koti-resort-shimla','The Deodar Kitchen','A warm, wood-panelled dining room serving Himachali thalis alongside north Indian and continental favourites, with a fireplace corner for late tea.','Himachali, North Indian, Continental','["https://qcenthotels.com/wp-content/uploads/2024/04/koti1.png"]','07:30 AM - 10:30 PM','60 covers','["Fireplace corner","Himachali thali","Buffet breakfast"]'),
('masaga-by-qcent-gurugram','Masaga Kitchen & Bar','An all-day dining room and bar for the business traveller, with a quick express lunch and a late-night menu.','Pan Asian, North Indian, Continental','["https://qcenthotels.com/wp-content/uploads/2024/04/masagaa.png"]','06:30 AM - 12:00 AM','70 covers','["Express business lunch","Bar","Late night menu"]'),
('the-aarambh-qcent-club-mukteshwar','Orchard Table','Farm-to-table Kumaoni cooking using produce from the surrounding orchards and village farms.','Kumaoni, Indian','["https://qcenthotels.com/wp-content/uploads/2024/04/5-11.png"]','08:00 AM - 10:00 PM','40 covers','["Farm-to-table","Bonfire dinners","Local Kumaoni menu"]')
) AS x(pslug,name,description,cuisine,images,timing,seating,features)
ON p.slug = x.pslug;

-- REVIEWS
INSERT INTO public.reviews (property_id,author_name,rating,title,body)
SELECT p.id, v.author, v.rating, v.title, v.body FROM public.properties p JOIN (VALUES
('qcent-woods-resort-spa-rishikesh','Ananya Sharma',5,'The forest cottage was magical','We stayed in the Luxury Woods Cottage for three nights. Waking up to birdsong and walking down to the river before breakfast is something we will not forget.'),
('qcent-woods-resort-spa-rishikesh','Rohit Menon',5,'Excellent food and service','The multi cuisine restaurant genuinely surprised us. The grill dinner by the fire was the highlight of the trip.'),
('qcent-woods-resort-spa-rishikesh','Farah Qureshi',4,'Peaceful and clean','Very well maintained, staff extremely courteous. Would have liked a longer stay.'),
('koti-resort-shimla','Vikram Bhatia',5,'Snow at the doorstep','Went in January and woke up to snow on the deck. The indoor pool and games barn kept the kids busy all day.'),
('masaga-by-qcent-gurugram','Sneha Kulkarni',4,'Reliable business stay','Quiet rooms, fast Wi-Fi and a very efficient front desk. Exactly what a work trip needs.'),
('the-aarambh-qcent-club-mukteshwar','Devansh Rao',5,'Nanda Devi from bed','Clear morning, snow peaks right there from the cottage window. The kitchen uses produce from their own orchard.')
) AS v(pslug,author,rating,title,body) ON p.slug = v.pslug;

